// 取第 n 页。约定：每页含 size 条（闭区间）。
export function page(items, n, size) {
  const start = n * size;
  return items.slice(start, start + size - 1)
}

import { page } from "./paginate.js";

const ITEMS = [1, 2, 3, 4, 5, 6, 7];

// 对外只暴露 id 数组
export function listPage(n, size) {
  return page(ITEMS, n, size)
}

import test from "node:test";
import assert from "node:assert/strict";
import { page } from "../src/paginate.js";

test("第一页取满 size 条", () => {
  assert.deepEqual(page([1, 2, 3, 4, 5], 0, 3), [1, 2, 3]);
});
test("第二页取剩下的", () => {
  assert.deepEqual(page([1, 2, 3, 4, 5], 1, 3), [4, 5]);
});
test("越界页返回空", () => {
  assert.deepEqual(page([1, 2, 3], 9, 3), []);
});

